        function getStoredCourses() {
            try {
                const saved = JSON.parse(localStorage.getItem('faridpurit_courses'));
                if (Array.isArray(saved) && saved.length > 0) return saved;
            } catch (e) {}
            return DEFAULT_COURSES;
        }

        function syncCoursesFromDB(sheetCourses = [], extraCourses = []) {
            const baseList = (Array.isArray(sheetCourses) && sheetCourses.length > 0) ? sheetCourses : getStoredCourses();
            const merged = Array.from(new Set([...baseList, ...extraCourses].map(c => String(c || '').trim()).filter(Boolean)));
            if (merged.length > 0) {
                localStorage.setItem('faridpurit_courses', JSON.stringify(merged));
                window.dispatchEvent(new Event('courses_updated'));
            }
        }

        function useGlobalCourses() {
            const [courses, setCourses] = useState(getStoredCourses);
            useEffect(() => {
                const handleSync = () => setCourses(getStoredCourses());
                window.addEventListener('courses_updated', handleSync);
                return () => window.removeEventListener('courses_updated', handleSync);
            }, []);
            const updateCourses = (newList) => {
                const cleanList = Array.from(new Set(newList.map(c => String(c || '').trim()).filter(Boolean)));
                localStorage.setItem('faridpurit_courses', JSON.stringify(cleanList));
                setCourses(cleanList);
                window.dispatchEvent(new Event('courses_updated'));
            };
            return [courses, updateCourses];
        }

