        function getAffiliateLevelInfo(revenue) {
            const reversedLevels = [...LEVEL_TIERS].reverse();
            return reversedLevels.find(l => revenue >= l.threshold) || LEVEL_TIERS[0];
        }

        function parseCustomDate(dateStr) {
            if (!dateStr) return new Date();
            const nativeDate = new Date(dateStr);
            if (!isNaN(nativeDate.getTime()) && !String(dateStr).match(/^[0-9]{2} [A-Z]{3} [0-9]{4}/i)) {
                return nativeDate;
            }
            const formats = [
                "DD MMM YYYY, hh:mm A", "DD MMM YYYY, hh:mm a", "D MMM YYYY, hh:mm A",
                "DD MMM YYYY HH:mm:ss", "D MMM YYYY HH:mm:ss",
                "M/D/YYYY, H:mm:ss", "MM/DD/YYYY, HH:mm:ss",
                "D/M/YYYY, H:mm:ss", "DD/MM/YYYY, HH:mm:ss",
                "YYYY-MM-DDTHH:mm:ss.SSSZ", "YYYY-MM-DD", "DD MMM YYYY"
            ];
            const strictParsed = moment(dateStr, formats, false);
            if(strictParsed.isValid()) return strictParsed.toDate();
            return new Date();
        }

        function toSafeYMD(val) {
            if (!val) return '';
            const s = String(val).replace(/^'/, '').trim();
            if (!s || s === '-' || s === 'Invalid date') return '';
            if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
            const m = moment(parseCustomDate(s));
            return m.isValid() ? m.format('YYYY-MM-DD') : '';
        }

        const playSound = (type) => {
            try {
                const AudioContext = window.AudioContext || window.webkitAudioContext;
                if (!AudioContext) return;
                const ctx = new AudioContext();
                const osc = ctx.createOscillator();
                const gain = ctx.createGain();
                osc.connect(gain);
                gain.connect(ctx.destination);
                
                if (type === 'action') {
                    osc.type = 'sine'; osc.frequency.setValueAtTime(600, ctx.currentTime);
                    gain.gain.setValueAtTime(0.05, ctx.currentTime);
                    osc.start(); osc.stop(ctx.currentTime + 0.05);
                } else if (type === 'success') {
                    osc.type = 'triangle'; 
                    osc.frequency.setValueAtTime(600, ctx.currentTime);
                    osc.frequency.setValueAtTime(800, ctx.currentTime + 0.1);
                    gain.gain.setValueAtTime(0.05, ctx.currentTime);
                    osc.start(); osc.stop(ctx.currentTime + 0.2);
                } else if (type === 'notify') {
                    osc.type = 'square'; 
                    osc.frequency.setValueAtTime(400, ctx.currentTime);
                    osc.frequency.setValueAtTime(600, ctx.currentTime + 0.15);
                    gain.gain.setValueAtTime(0.05, ctx.currentTime);
                    gain.gain.linearRampToValueAtTime(0, ctx.currentTime + 0.3);
                    osc.start(); osc.stop(ctx.currentTime + 0.3);
                } else if (type === 'cancel') {
                    osc.type = 'sawtooth';
                    osc.frequency.setValueAtTime(300, ctx.currentTime);
                    osc.frequency.setValueAtTime(150, ctx.currentTime + 0.2);
                    gain.gain.setValueAtTime(0.05, ctx.currentTime);
                    osc.start(); osc.stop(ctx.currentTime + 0.2);
                }
            } catch(e) { console.log("Audio not supported"); }
        };

