                                                        <div className="flex items-center gap-1.5 flex-wrap">
                                                            <button 
                                                                onClick={(e) => { e.stopPropagation(); navigator.clipboard.writeText(lead.email); if(typeof window.playSound === 'function') window.playSound('action'); addToast("Email copied!", "success"); }} 
                                                                className="text-[10px] text-gray-500 dark:text-gray-400 truncate font-semibold hover:text-[#005fb8] dark:hover:text-[#60cdff] transition-colors text-left flex items-center gap-1.5 min-w-0 flex-1" 
                                                                title="Copy Email"
                                                            >
                                                                <Icon name="mail" className="w-3 h-3 shrink-0 opacity-70" /> <span className="truncate">{lead.email}</span>
                                                            </button>
                                                            {checkDup(lead.email, 'email') && <span className="bg-red-50 text-red-600 border border-red-200 dark:bg-red-900/40 dark:border-red-800/60 dark:text-red-400 text-[8px] font-bold px-1 py-0.5 rounded-sm uppercase tracking-widest whitespace-nowrap leading-none shrink-0 shadow-sm" title="Duplicate Email">DUP</span>}
                                                        </div>
