                                    {sidebarBadges.community > 0 && <span className="absolute -top-1.5 -right-2 min-w-[15px] h-[15px] px-1 rounded-full bg-rose-500 text-white text-[8px] font-numbers font-bold flex items-center justify-center">{sidebarBadges.community > 99 ? '99+' : sidebarBadges.community}</span>}
